<template>
  <q-card flat class="popup-background">
    <q-toolbar class="pr-0 secondary-toolbar">
      <q-toolbar-title>
        <span class="text-white text-h6 text-weight-bold">
          {{ $t('add_a_task') }}
        </span>
      </q-toolbar-title>

      <f-btn
        class="text-white q-mr-xs"
        flat
        round
        dense
        appearance="tertiary"
        icon="close"
        @click="$emit('closeCreatePopup')"
      />
    </q-toolbar>

    <q-separator class="separator-space" />
    <q-card-section class="q-pa-md">
      <div class="q-mt-md">
        <q-input
          dense
          outlined
          v-model="model.title"
          class="back-white"
          :label="$t('name')"
        >
          <template v-slot:append>
            <q-icon
              v-if="errors.hasOwnProperty('title') && errors['title'] != ''"
              flat
              dense
              name="error"
              size="24px"
              color="red"
            >
              <q-tooltip class="bg-red line-error-tooltip">
                {{ errors['title'] }}
              </q-tooltip>
            </q-icon>
          </template>
        </q-input>
      </div>

      <div class="q-mt-md">
        <q-select
          dense
          outlined
          :options="taskTypeOptions"
          class="back-white"
          v-model="model.is_notification"
          :label="$t('task_type')"
          emit-value
          map-options
        />
      </div>

      <div class="q-mt-md">
        <q-select
          dense
          outlined
          :options="priorityOptions"
          class="back-white"
          v-model="model.priority"
          :label="$t('priority')"
          emit-value
          map-options
        />
      </div>

      <div class="q-mt-md">
        <q-select
          dense
          outlined
          :options="statusOptions"
          class="back-white"
          v-model="model.status"
          :label="$t('status')"
          emit-value
          map-options
        />
      </div>

      <div class="q-mt-md">
        <q-input
          dense
          outlined
          readonly
          class="back-white"
          v-model="model.deadline"
          :label="$t('deadline')"
        >
          <template v-slot:append>
            <q-icon name="event" class="cursor-pointer" @click.stop>
              <q-tooltip>Select Date-Time</q-tooltip>
              <q-popup-proxy
                cover
                v-model="show_calender"
                transition-show="scale"
                transition-hide="scale"
                ref="qDateProxy"
              >
                <q-date
                  v-model="model.date"
                  @update:model-value="
                    (val: any) => {
                      OnDateChange(val);
                    }
                  "
                  minimal
                >
                  <div class="row items-center">
                    <q-icon
                      name="schedule "
                      class="icon-grey q-mr-sm"
                      size="20px"
                    />
                    <q-select
                      dense
                      outlined
                      :options="timeOptions"
                      class="back-white"
                      v-model="model.time"
                      @update:model-value="
                        (val: any) => {
                          OnTimeChange(val);
                        }
                      "
                      :label="$t('set_time')"
                      emit-value
                      map-options
                    />
                  </div>
                  <div class="row items-center justify-end q-gutter-sm">
                    <f-btn
                      :label="$t('close')"
                      appearance="negative-tertiary"
                      v-close-popup
                    />
                    <f-btn label="Ok" appearance="tertiary" v-close-popup />
                  </div>
                </q-date>
              </q-popup-proxy>
            </q-icon>
          </template>
        </q-input>
      </div>

      <div class="q-mt-md">
        <q-checkbox
          v-model="model['assigned_to_group']"
          :label="$t('assigned_to_group')"
          @update:model-value="resetAssigned"
        />
      </div>

      <div class="q-mt-md">
        <q-checkbox
          v-model="model['send_email']"
          :label="$t('send_email')"
        />
      </div>

      <div class="q-mt-md" v-if="model['assigned_to_group']">
        <q-select
          clearable
          use-input
          dense
          outlined
          @filter="filterGroupsEvent"
          :options="filteredGroupList"
          :loading="groups_loading"
          emit-value
          map-options
          class="back-white"
          v-model="model.assigned_to_group_id"
          :label="$t('assigned_to_group')"
          hide-dropdown-icon
        >
          <template v-slot:selected-item="scope">
            <div class="ellipsis">{{ scope.opt.label }}</div>
          </template>
          <template v-slot:no-option>
            <q-item>
              <q-item-section> No results </q-item-section>
            </q-item>
          </template>
          <template v-slot:append>
            <q-icon
              v-if="
                errors.hasOwnProperty('assigned_to_group_id') &&
                errors['assigned_to_group_id'] != ''
              "
              flat
              dense
              name="error"
              size="24px"
              color="red"
            >
              <q-tooltip class="bg-red line-error-tooltip">
                {{ errors['assigned_to_group_id'] }}
              </q-tooltip>
            </q-icon>
          </template>
        </q-select>
      </div>

      <div class="q-mt-md" v-if="!model['assigned_to_group']">
        <q-select
          clearable
          use-input
          dense
          outlined
          hide-dropdown-icon
          @filter="filterUsersEvent"
          :options="filteredUserList"
          :loading="user_list_loading"
          emit-value
          map-options
          class="back-white"
          v-model="model.assigned_to_user_id"
          :label="$t('assigned_to')"
        >
          <template v-slot:append>
            <q-icon
              v-if="
                errors.hasOwnProperty('assigned_to_user_id') &&
                errors['assigned_to_user_id'] != ''
              "
              flat
              dense
              name="error"
              size="24px"
              color="red"
            >
              <q-tooltip class="bg-red line-error-tooltip">
                {{ errors['assigned_to_user_id'] }}
              </q-tooltip>
            </q-icon>
          </template>
          <template v-slot:no-option>
            <q-item>
              <q-item-section> No results </q-item-section>
            </q-item>
          </template>
        </q-select>
      </div>

      <div class="q-mt-md">
        <q-input
          dense
          outlined
          v-model="model.description"
          class="back-white"
          :label="$t('description')"
          type="textarea"
        />
      </div>
    </q-card-section>

    <q-card-actions align="right">
      <f-btn
        appearance="cancel"
        :label="$t('cancel')"
        @click="$emit('closeCreatePopup')"
      />
      <f-btn :label="$t('create')" @click="save" class="q-mr-sm" />
    </q-card-actions>
  </q-card>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import {
  useDocumentStore,
  useDropdownStore,
  useGroupDropdownStore,
  useTaskStore,
} from 'src/store/main';
import { taskApiService } from 'src/services';
import type { dynamicObj } from 'src/pages/assets';
import { priority_list, status_list } from 'src/constants/enum';
import { date } from 'quasar';
import { ApiExceptions } from 'src/exceptions/index';
import { notify } from 'src/components/notifications/notify';

const { addToDate } = date;

export default defineComponent({
  props: {},
    emits: ['closeCreatePopup', 'refreshTasks'],
  watch: {
    doc_loaded: {
      handler: function (newVal, oldVal) {
        this.initView();
      },
    },
  },
  components: {},
  data() {
    return {
      taskTypeOptions: [
        { label: this.$t('task'), value: false },
        { label: this.$t('notification'), value: true },
      ],
    };
  },
  mounted: function () {
    this.initView();
  },
  methods: {
    initView() {
      try {
        this.priorityOptions = priority_list.map((item: any) => {
          return {
            label: this.$t(item),
            value: item,
          };
        });

        this.statusOptions = status_list.map((item: any) => {
          return {
            label: this.$t(item),
            value: item,
          };
        });

        this.makeTimeOptions();
        this.loadUserList();
        this.loadGroupsList();

        this.model.time = this.getDeadlineTime();
        this.model.is_notification = this.taskTypeOptions[0].value;
        this.model.priority = 'medium';
        this.model.status = 'open';
        this.model.assigned_to_group = false;
        this.model.assigned_to_user_id = null;
        this.model.send_email = true;

        const newDate = addToDate(new Date(), { days: 1 });
        this.model.date = date.formatDate(newDate, this.task_date_format);
        this.model.deadline = this.makeDeadline(
          this.model.time,
          this.model.date,
        );
      } catch (error) {
        logError(error);
      }
    },

    loadUserList() {
      this.filteredUserList = this.usersList;
    },

    loadGroupsList() {
      this.filteredGroupList = this.group_list;
    },

    OnTimeChange(time: any) {
      const deadline = this.makeDeadline(time, this.model.date);
      this.model.deadline = deadline;
    },

    OnDateChange(date: any) {
      const deadline = this.makeDeadline(this.model.time, date);
      this.model.deadline = deadline;
    },

    filterGroupsEvent(val: string, update: any, abort: any) {
      if (val.length < 1) {
        abort();
        return;
      }

      update(() => {
        const needle = val.toLowerCase();
        this.filteredGroupList = this.group_list.filter(
          (v: any) => v.label.toLowerCase().startsWith(needle) as string,
        );
      });
    },

    filterUsersEvent(val: string, update: any, abort: any) {
      if (val.length < 1) {
        abort();
        return;
      }

      update(() => {
        const needle = val.toLowerCase();
        this.filteredUserList = this.usersList.filter(
          (v: any) => v.label.toLowerCase().startsWith(needle) as string,
        );
      });
    },

    // save
    async save() {
      try {
        if (!this.validateForm()) {
          return;
        }

        const data = {} as dynamicObj;
        data['title'] = this.model.title;
        data['is_notification'] = this.model.is_notification;
        data['priority'] = this.model.priority;
        data['status'] = this.model.status;
        data['deadline'] = this.getIsoFormatDate(this.model.deadline);
        data['send_email'] = this.model.send_email !== false;

        if (this.model.assigned_to_group) {
          data['assigned_to_group_id'] = this.model.assigned_to_group_id;
        } else {
          data['assigned_to_user_id'] = this.model.assigned_to_user_id;
        }

        if (this.model.description) {
          data['description'] = this.model.description;
        }

        if (this.record && this.record.doc_id) {
          data['document_id'] = this.record.doc_id;
        }

        const response = await taskApiService.createTask(data);
        if (response.success === false) {
          throw response;
        }

        this.$emit('closeCreatePopup');
        this.$emit('refreshTasks');
        const event = new CustomEvent('refreshTasks', {});
        document.dispatchEvent(event);
      } catch (error) {
        const msg = ApiExceptions.getErrorMessage(error as dynamicObj);
        notify.error(msg);
        logError(error);
      } finally {
        this.processing = false;
      }
    },

    validateForm() {
      this.errors = {} as dynamicObj;
      let valid = true;

      if (!this.model.title) {
        this.errors['title'] = this.$t('field_required');
        valid = false;
      }

      if (this.model.assigned_to_group) {
        if (!this.model.assigned_to_group_id) {
          this.errors['assigned_to_group_id'] = this.$t('field_required');
          valid = false;
        }
      } else {
        if (!this.model.assigned_to_user_id) {
          this.errors['assigned_to_user_id'] = this.$t('field_required');
          valid = false;
        }
      }

      return valid;
    },

    resetAssigned() {
      this.errors['assigned_to_group_id'] = '';
      this.errors['assigned_to_user_id'] = '';
    },
  },

  setup() {
    const doc_store = useDocumentStore();
    const { record } = storeToRefs(doc_store);

    const dropdown_store = useDropdownStore();
    const filteredUserList: any = ref(dropdown_store.usersList);
    const { user_list_loading, usersList } = storeToRefs(dropdown_store);

    const group_dropdown_store = useGroupDropdownStore();
    const filteredGroupList: any = ref(group_dropdown_store.group_list);
    const { group_list, groups_loading } = storeToRefs(group_dropdown_store);

    const task_store = useTaskStore();
    const { timeOptions, task_date_format } = storeToRefs(task_store);
    const { makeTimeOptions, getDeadlineTime, getIsoFormatDate, makeDeadline } =
      task_store;

    return {
      makeDeadline,
      getIsoFormatDate,
      getDeadlineTime,
      task_date_format,
      makeTimeOptions,

      group_list,
      groups_loading,
      filteredGroupList,

      user_list_loading,
      usersList,
      filteredUserList,

      record,

      createTaskPopup: ref(false),
      model: ref({} as dynamicObj),
      priorityOptions: ref([] as dynamicObj[]),
      statusOptions: ref([] as dynamicObj[]),
      show_calender: ref(false),
      timeOptions,
      errors: ref({} as dynamicObj),
      processing: ref(false),
    };
  },
});
</script>

<style lang="scss" scoped></style>
